-- Function (returns value)
CREATE FUNCTION is_valid_email(s TEXT) RETURNS BOOLEAN AS $$
  SELECT s ~* '^[^@]+@[^@]+$';
$$ LANGUAGE sql;

SELECT is_valid_email('a@b.com');

-- Procedure
CREATE PROCEDURE log_audit(p TEXT) LANGUAGE sql AS $$
  INSERT INTO audit_log(msg) VALUES (p);
$$;
CALL log_audit('user created');

-- Trigger
CREATE TRIGGER trg_audit AFTER INSERT ON users
FOR EACH ROW EXECUTE FUNCTION log_audit('new user');

