-- Add FTS index
ALTER TABLE posts ADD COLUMN body_tsv tsvector;
CREATE INDEX posts_tsv_idx ON posts USING GIN (body_tsv);

-- populate
UPDATE posts SET body_tsv = to_tsvector('english', body);

-- search
SELECT id, ts_rank(body_tsv, query) AS rank
FROM posts, to_tsquery('english', 'cat & fast') AS query
WHERE body_tsv @@ query
ORDER BY rank DESC;

-- Note: to_tsvector expensive — trigger/store keep updated.

